import{z as i,x as B,o as r,c as p,q as E,j as l,D as n,d as t,s,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Kydland–Prescott 规则优于权变","description":"","frontmatter":{"title":"Kydland–Prescott 规则优于权变","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/kydland-prescott.md","filePath":"econ/kydland-prescott.md","lastUpdated":1791413859000}'),A={name:"econ/kydland-prescott.md"};function c(m,a,h,u,D,f){const o=B("Mermaid");return r(),p("div",null,[a[2]||(a[2]=E('<h1 id="kydland–prescott-规则优于权变" tabindex="-1">Kydland–Prescott 规则优于权变 <a class="header-anchor" href="#kydland–prescott-规则优于权变" aria-label="Permalink to &quot;Kydland–Prescott 规则优于权变&quot;">​</a></h1><div class="epigraph"><p>最优控制把未来政策当成给定路径；私人预期该路径之后，计划在事后不再最优。规则可以优于相机抉择。</p><footer>—— Kydland and Prescott, Rules Rather than Discretion: The Inconsistency of Optimal Plans, Journal of Political Economy 1977</footer></div><p><a href="/econ/friedman-quantity">上一课</a>（Friedman 货币数量重述）。附录对照。主干<a href="/econ/time-inconsistency">时间不一致与承诺</a>已取通胀偏误与承诺价值。本篇对照 <strong>1977 年原文</strong>：问题不是央行无知或偏好通胀，而是动态规划在私人前瞻时不能按「每期重新最优」来用。不把 1982 年 <em>Time to Build</em> 的 RBC 校准写进来——那是另一篇，见主干<a href="/econ/rbc-contrast">真实经济周期对照</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最优控制（当时宏观政策的标准工具）假设政策是对状态的反馈，未来行动对今天的私人决策像天气一样外生。Kydland 与 Prescott 指出：若私人的今天选择依赖对未来政策的信念，而政策知道这一点，那么「宣布一条路径再在未来重新优化」一般时间不一致。洪水保险、专利、资本税、菲利普斯曲线上的通胀，都是同一结构。缺口是：时间一致的相机政策可以系统性差于事先绑住的规则。</p><p>通胀例子后来被 Barro–Gordon 写熟，但 1977 年已经用菲利普斯曲线给出：事先想要低通胀以锚定预期，事后想利用给定预期用通胀换就业。权变均衡停在偏高的通胀，就业没有多得。</p><p><span class="marginnote">时间不一致不是「政策朝令夕改」的同义反复。它可以是完全预见下的子博弈结果：每个时点的最优都兑现，只是整体路径差于有承诺的路径。Calvo 1978 同期独立讨论了类似结构。</span></p><p><span class="marginnote">直觉类比：家长事前宣布「考前不许玩游戏」，孩子因此安心复习；到了考前又觉得「这次就算了吧」。事后原谅总更省事，但只要孩子预期到你会松口，事前就不会复习——每一刻都「最优」，加起来却是最差的方案。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两期或无限期，政策目标含通胀与就业（或资本积累），私人先形成预期或先投资。有承诺：政策在 \\(t=0\\) 选出全路径，受预期一致性约束。无权变约束：从每一期的子问题再解一次。两者一般不再重合。规则是事先把可行集切小（固定增长率、固定税率日程），使事后没有可利用的工具，从而预期停在好的点上。</p>',10)),(r(),l(d,null,{default:n(()=>[s(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMM%5B%22t%3D0%20%E6%89%BF%E8%AF%BA%E5%85%A8%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20GOOD%5B%22%E4%BD%8E%E9%80%9A%E8%83%80%E5%9D%87%E8%A1%A1%22%5D%0A%20%20DISC%5B%22%E9%80%90%E6%9C%9F%E5%86%8D%E4%BC%98%E5%8C%96%22%5D%20--%3E%20BIAS%5B%22%E9%80%9A%E8%83%80%E5%81%8F%E8%AF%AF%2C%20%E5%B0%B1%E4%B8%9A%E6%9C%AA%E6%94%B9%E5%96%84%22%5D%0A%20%20RULE%5B%22%E7%BB%91%E4%BD%8F%E5%B7%A5%E5%85%B7%E7%9A%84%E8%A7%84%E5%88%99%22%5D%20--%3E%20GOOD%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[t("原文强调：即使政策目标就是社会福利，不一致仍发生。问题不是恶意，是约束。与"),e("a",{href:"/econ/lucas-critique"},"卢卡斯批判"),t("的对照：卢卡斯说结构参数随政策变；KP 说即使你用对了结构，逐期最优仍可能不是最优计划。两篇都反对「把宏观计量当控制工程」，机制不同。")],-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：「权变」就是每期看着情况重新决定；「规则」是事前把工具绑死（如法律写死通胀目标或税率日程）。规则看着笨——白扔了灵活性——但私人预期从此不再被反复利用，等于用「不可信的灵活」换回「可信的承诺」。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制是今天的政策工具出现在昨天的约束里。专利若可在发明后废除，发明事前不发生；资本税若可在安装后加征，投资事前萎缩。通胀亦然：预期一旦形成，短期权变的边际变了。规则通过放弃事后灵活性，买回事前的激励。Friedman 1956 的货币需求稳定并不自动给出规则；1977 才把「为什么要绑住」写成一般动态。",-1)),(r(),l(d,null,{default:n(()=>[s(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOOL%5B%22%E5%B7%A5%E5%85%B7%E5%8F%AF%E4%BA%8B%E5%90%8E%E5%8A%A8%E7%94%A8%22%5D%20--%3E%20EXP%5B%22%E7%A7%81%E4%BA%BA%E9%A2%84%E8%A7%81%E5%88%B0%E5%86%8D%E4%BC%98%E5%8C%96%22%5D%0A%20%20EXP%20--%3E%20NOINV%5B%22%E4%BA%8B%E5%89%8D%E5%B0%91%E6%8A%95%E8%B5%84%3A%20%E5%B0%91%E5%8F%91%E6%98%8E%22%5D%0A%20%20NOINV%20--%3E%20POOR%5B%22%E4%BA%8B%E5%90%8E%E7%BB%93%E6%9E%9C%E6%9B%B4%E5%B7%AE%22%5D%0A%20%20RULE%5B%22%E8%A7%84%E5%88%99%3A%20%E4%BA%8B%E5%85%88%E6%94%BE%E5%BC%83%E5%B7%A5%E5%85%B7%22%5D%20--%3E%20SAFE%5B%22%E9%A2%84%E6%9C%9F%E4%B8%8D%E8%A2%AB%E5%8F%8D%E5%A4%8D%E5%88%A9%E7%94%A8%22%5D%0A%20%20SAFE%20--%3E%20INV%5B%22%E4%BA%8B%E5%89%8D%E6%8A%95%E8%B5%84%E7%85%A7%E5%B8%B8%E5%8F%91%E7%94%9F%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<h3 id="对照主干时间不一致-不是-rbc" tabindex="-1">对照主干时间不一致，不是 RBC <a class="header-anchor" href="#对照主干时间不一致-不是-rbc" aria-label="Permalink to &quot;对照主干时间不一致，不是 RBC&quot;">​</a></h3><p>主干<a href="/econ/time-inconsistency">时间不一致</a>已用承诺问题。附录对照原文：例子含专利、洪水保险、通胀—失业，不只是菲利普斯。规则优于权变，不是因为规则天真，而是因为规则改变预期从而改变约束集。承诺的可以是状态依存规则，只要不被逐期再优化掉。「Time to Build」1982 是另一条线，不要写进这篇 JPE。</p><p><span class="marginnote">Kydland and Prescott, <em>JPE</em> 85(3), 1977, 473–491。Rules Rather than Discretion。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本文写成「规则永远优于灵活」。承诺的技术、声誉、委托独立央行，都是后文对「如何绑」的补充；原文只比较理想承诺与逐期权变。也不要把泰勒规则当成 1977 的结论——<a href="/econ/taylor-rule">泰勒</a>是 1990 年代的反馈描述。RBC 的校准宏观是 Prescott 另一条线，附录题目既已写「规则优于权变」，就停在 1977。</p><p><span class="marginnote">常见误区：把本文读成「央行必须用死板的固定规则」。原文比较的是理想承诺与逐期权变两个极端；独立央行、声誉机制、状态依存规则都是后来「如何绑住手」的补充。1977 的贡献是诊断「为什么会不一致」，不是开出某一味具体的药。</span></p><p>下一篇对照 Woodford 如何在新凯恩斯约束下，把利率规则写成可决定价格水平的系统。</p><p>时间不一致不是决策者「变心」，是子博弈上的最优偏离了原计划。承诺的可以是状态依存规则，只要规则本身不被逐期拆掉。</p><p>Bagehot 把最后贷款人写成事前三句，已经是同一逻辑。本附录不重写窗口操作。</p><p>专利与洪水保险说明：离开货币，承诺问题仍在。课堂常只摘通胀，原文不是这样。</p><p>1977 年没有校准 RBC 的二阶矩，也没有估计泰勒系数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Kydland–Prescott 1977：前瞻私人使逐期最优控制时间不一致。</li><li>规则可以优于权变，即使目标函数相同。</li><li>不是 1982 年 RBC 论文。</li><li>出处：Kydland and Prescott, <em>JPE</em> 1977。</li></ul>',13))])}const _=i(A,[["render",c]]);export{C as __pageData,_ as default};
